"""Academy Year 8 revision set 2: integers, formulae and equations, sequences and functions, graphs, collecting data, probability."""
import json, pathlib
from acad1 import F, Q, sheet, x, y, n
from diagrams import graph

def T(rows, head=True):
    """A small table: rows of cells; the first row is a header row when head is True."""
    out = []
    for i, r in enumerate(rows):
        tag = "th" if head and i == 0 else "td"
        out.append("<tr>" + "".join(f"<{tag}>{c}</{tag}>" for c in r) + "</tr>")
    return f'<table class="tbl">{"".join(out)}</table>'

